UPDATE "Serial"
SET "status" = 'out',
    "outboundTime" = CURRENT_TIMESTAMP
WHERE "itemId" = #{itemId}
  AND "serialNo" = #{serialNo}
  AND "status" = 'in_stock'
  AND "warehouseId" = #{warehouseId}

UPDATE "Serial"
SET "warehouseId" = #{toWarehouseId}
WHERE "itemId" = #{itemId}
  AND "serialNo" = #{serialNo}
  AND "status" = 'in_stock'
  AND "warehouseId" = #{fromWarehouseId}
